-- ===================================================
-- TẠO BẢNG (NẾU CHƯA CÓ)
-- ===================================================

CREATE TABLE IF NOT EXISTS provinces (
    id VARCHAR(50) PRIMARY KEY,
    full_name VARCHAR(255) NOT NULL,
    short_name VARCHAR(100),
    lat DECIMAL(10, 8),
    lng DECIMAL(11, 8),
    code VARCHAR(20) UNIQUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS wards (
    id VARCHAR(50) PRIMARY KEY,
    full_name VARCHAR(255) NOT NULL,
    short_name VARCHAR(100),
    lat DECIMAL(10, 8),
    lng DECIMAL(11, 8),
    code VARCHAR(20) UNIQUE,
    province_id VARCHAR(50) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (province_id) REFERENCES provinces(id) ON DELETE CASCADE
);
-- Index cho provinces
CREATE INDEX IF NOT EXISTS idx_provinces_code ON provinces(code);
CREATE INDEX IF NOT EXISTS idx_provinces_name ON provinces(full_name);
CREATE INDEX IF NOT EXISTS idx_provinces_coords ON provinces(lat, lng);
CREATE INDEX IF NOT EXISTS idx_provinces_short_name ON provinces(short_name);
CREATE INDEX IF NOT EXISTS idx_provinces_created_at ON provinces(created_at);

-- Index cho wards
CREATE INDEX IF NOT EXISTS idx_wards_code ON wards(code);
CREATE INDEX IF NOT EXISTS idx_wards_name ON wards(full_name);
CREATE INDEX IF NOT EXISTS idx_wards_coords ON wards(lat, lng);
CREATE INDEX IF NOT EXISTS idx_wards_short_name ON wards(short_name);
CREATE INDEX IF NOT EXISTS idx_wards_province_id ON wards(province_id);
CREATE INDEX IF NOT EXISTS idx_wards_created_at ON wards(created_at);

-- Composite index cho tìm kiếm theo province
CREATE INDEX IF NOT EXISTS idx_wards_province_name ON wards(province_id, full_name);
CREATE INDEX IF NOT EXISTS idx_wards_province_coords ON wards(province_id, lat, lng);

